import"./chunk-VC46IEJQ.js";var e={id:"dragonstone",intro:{en:"A volcanic island at the mouth of Blackwater Bay, crowned by a black castle whose towers and gargoyles were shaped as dragons and other beasts. It was the Targaryens' first stronghold in Westeros; in the novels it is Stannis Baratheon's seat as he presses his claim. The books give the castle's character and a handful of named places, not a plan.",zh:"\u9ED1\u6C34\u6E7E\u53E3\u7684\u4E00\u5EA7\u706B\u5C71\u5C9B\uFF0C\u5C9B\u4E0A\u9ED1\u8272\u57CE\u5821\u7684\u5854\u697C\u4E0E\u6EF4\u6C34\u517D\u88AB\u5851\u6210\u5DE8\u9F99\u4E0E\u79CD\u79CD\u602A\u517D\u3002\u8FD9\u91CC\u662F\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u5728\u7EF4\u65AF\u7279\u6D1B\u7684\u7B2C\u4E00\u5904\u636E\u70B9\uFF1B\u5C0F\u8BF4\u4E2D\uFF0C\u53F2\u5766\u5C3C\u65AF\xB7\u62DC\u62C9\u5E2D\u6069\u4EE5\u6B64\u4E3A\u6839\u57FA\u4E89\u593A\u738B\u4F4D\u3002\u4E66\u4E2D\u53EA\u4EA4\u4EE3\u4E86\u57CE\u5821\u7684\u6C14\u8D28\u4E0E\u5C11\u6570\u51E0\u5904\u5730\u540D\uFF0C\u5E76\u65E0\u5E73\u9762\u56FE\u3002"},notes:{en:`From the books: the island and its smoking mountain, Dragonmont; a castle of black stone shaped by Valyrian craft into dragons, gargoyles and other monsters; the Stone Drum as central keep, with the Chamber of the Painted Table at its top; a Great Hall entered through a dragon's jaws; the Sea Dragon Tower; a harbour and village below. Invented: the plan, positions, building shapes, the village, the carved details and the table's outline. The "dragon-mouth gate" is our adaptation of the Great Hall's entrance.`,zh:"\u4E66\u4E2D\u786E\u7ACB\uFF1A\u5C9B\u5C7F\u53CA\u5192\u70DF\u7684\u706B\u5C71\u9F99\u5C71\uFF1B\u4EE5\u74E6\u96F7\u5229\u4E9A\u6280\u827A\u5851\u6210\u5DE8\u9F99\u3001\u6EF4\u6C34\u517D\u4E0E\u79CD\u79CD\u602A\u7269\u7684\u9ED1\u77F3\u57CE\u5821\uFF1B\u4F5C\u4E3A\u4E3B\u5821\u7684\u77F3\u9F13\u697C\uFF0C\u5176\u9876\u5C42\u4E3A\u5F69\u7ED8\u684C\u5385\uFF1B\u987B\u4ECE\u9F99\u53E3\u8FDB\u5165\u7684\u5927\u5385\uFF1B\u6D77\u9F99\u5854\uFF1B\u57CE\u4E0B\u7684\u6E2F\u53E3\u4E0E\u6751\u843D\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6574\u4F53\u5E03\u5C40\u3001\u4F4D\u7F6E\u3001\u5EFA\u7B51\u9020\u578B\u3001\u6751\u843D\u3001\u96D5\u9970\u7EC6\u8282\u4E0E\u684C\u9762\u8F6E\u5ED3\u3002\u201C\u9F99\u53E3\u95E8\u201D\u662F\u672C\u573A\u666F\u5BF9\u5927\u5385\u5165\u53E3\u7684\u6539\u7F16\u3002"},tour:["harbor-village","dragonmont","castle-walls","dragon-gargoyles","sea-dragon-gate","stone-drum","painted-table-chamber","dragonglass-slopes"],sources:[{ref:"acok",checked:"memory",note:{en:"Dragonstone appears in the prologue (Maester Cressen) and in Davos chapters; details recalled from the novels, not re-read.",zh:"\u9F99\u77F3\u5C9B\u89C1\u4E8E\u5E8F\u7AE0\uFF08\u514B\u793C\u68EE\u5B66\u58EB\uFF09\u4E0E\u6234\u4F5B\u65AF\u7684\u7AE0\u8282\uFF1B\u7EC6\u8282\u51ED\u5BF9\u5C0F\u8BF4\u7684\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:`Search summaries of the wiki and the Westeros.org concordance confirmed the Stone Drum (named for the booming of its walls in storms), the Painted Table at its top, the Great Hall's dragon-mouth entrance and the Sea Dragon Tower. No "Sea Dragon Gate" was found. Pages not fetched.`,zh:"\u7EF4\u57FA\u4E0E Westeros.org \u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\uFF1A\u77F3\u9F13\u697C\uFF08\u56E0\u98CE\u66B4\u4E2D\u5899\u4F53\u9686\u9686\u4F5C\u54CD\u800C\u5F97\u540D\uFF09\u3001\u5176\u9876\u5C42\u7684\u5F69\u7ED8\u684C\u3001\u5927\u5385\u7684\u9F99\u53E3\u5165\u53E3\u4EE5\u53CA\u6D77\u9F99\u5854\u3002\u672A\u627E\u5230\u201C\u6D77\u9F99\u95E8\u201D\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}},{ref:"asos",checked:"memory",note:{en:"Dragonglass under Dragonstone is raised in later books. Recalled; the exact chapter was not rechecked.",zh:"\u9F99\u77F3\u5C9B\u5730\u4E0B\u85CF\u6709\u9F99\u6676\u4E00\u4E8B\u5728\u540E\u7EED\u5404\u5377\u4E2D\u88AB\u63D0\u53CA\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u590D\u6838\u5177\u4F53\u7AE0\u8282\u3002"}},{ref:"maps",checked:"not-accessed",note:{en:"No island map was available; the arrangement of mountain, castle and harbour is an artistic choice.",zh:"\u672A\u80FD\u67E5\u9605\u5C9B\u5C7F\u5730\u56FE\uFF1B\u5C71\u3001\u5821\u3001\u6E2F\u7684\u76F8\u5BF9\u4F4D\u7F6E\u4E3A\u827A\u672F\u5904\u7406\u3002"}}],landmarks:{dragonmont:{name:{en:"Dragonmont",zh:"\u9F99\u5C71"},desc:{en:"The smoking mountain that dominates the island, trailing ash and steam above black slopes.",zh:"\u4E3B\u5BB0\u5168\u5C9B\u7684\u5192\u70DF\u706B\u5C71\uFF0C\u9ED1\u8272\u5C71\u5761\u4E4B\u4E0A\u62D6\u7740\u4E00\u7F15\u7070\u70DF\u4E0E\u84B8\u6C7D\u3002"},tour:{en:"Dragonmont smokes above the castle; legend says dragons once hatched in its fires.",zh:"\u9F99\u5C71\u5728\u57CE\u5821\u4E0A\u65B9\u5192\u7740\u70DF\uFF1B\u76F8\u4F20\u5DE8\u9F99\u66FE\u5728\u5B83\u7684\u706B\u4E2D\u5B75\u5316\u3002"},source:{confidence:"high",refs:["acok","twoiaf"],book:{en:"A smoking mountain, Dragonmont, rises behind the castle.",zh:"\u5192\u70DF\u7684\u9F99\u5C71\u8038\u7ACB\u4E8E\u57CE\u5821\u4E4B\u540E\u3002"},unknown:{en:"Its height, crater shape and how active it is.",zh:"\u9AD8\u5EA6\u3001\u706B\u5C71\u53E3\u5F62\u72B6\u53CA\u6D3B\u8DC3\u7A0B\u5EA6\u3002"},interpretation:{en:"A tall cone with a crater, steam vents and a glowing ember patch; scale exaggerated.",zh:"\u5E26\u706B\u5C71\u53E3\u7684\u9AD8\u8038\u9525\u4F53\uFF0C\u8F85\u4EE5\u55B7\u6C14\u5B54\u4E0E\u6697\u7EA2\u4F59\u70EC\uFF1B\u5C3A\u5EA6\u6709\u6240\u5938\u5927\u3002"}}},"stone-drum":{name:{en:"Stone Drum",zh:"\u77F3\u9F13\u697C"},desc:{en:"The castle's central keep, a massive round tower of black stone named for the way its walls boom in a storm.",zh:"\u57CE\u5821\u7684\u4E3B\u5821\uFF0C\u4E00\u5EA7\u9ED1\u77F3\u780C\u6210\u7684\u5DE8\u5927\u5706\u697C\uFF0C\u56E0\u98CE\u66B4\u4E2D\u5899\u4F53\u9686\u9686\u4F5C\u54CD\u800C\u5F97\u540D\u3002"},tour:{en:"The Stone Drum is the castle's heart; in storms its walls boom like a drum.",zh:"\u77F3\u9F13\u697C\u662F\u57CE\u5821\u7684\u6838\u5FC3\uFF1B\u6BCF\u9022\u98CE\u66B4\uFF0C\u5899\u4F53\u4FBF\u5982\u64C2\u9F13\u822C\u8F70\u9E23\u3002"},source:{confidence:"high",refs:["acok","awoiaf"],book:{en:"The Stone Drum is the central keep, named for the booming of its walls in storms; the Chamber of the Painted Table is at its top.",zh:"\u77F3\u9F13\u697C\u662F\u4E3B\u5821\uFF0C\u56E0\u98CE\u66B4\u4E2D\u5899\u4F53\u8F70\u9E23\u800C\u5F97\u540D\uFF1B\u5F69\u7ED8\u684C\u5385\u4F4D\u4E8E\u5176\u9876\u5C42\u3002"},unknown:{en:"Height, diameter and interior layout.",zh:"\u9AD8\u5EA6\u3001\u76F4\u5F84\u4E0E\u5185\u90E8\u5E03\u5C40\u3002"},interpretation:{en:"A tall drum with a crowned upper cylinder and slate dome, ringed by fourteen carved drakes.",zh:"\u9AD8\u5927\u7684\u5706\u697C\uFF0C\u9876\u90E8\u518D\u53E0\u4E00\u8282\u5706\u7B52\u4E0E\u677F\u5CA9\u7A79\u9876\uFF0C\u73AF\u5217\u5341\u56DB\u5934\u77F3\u9F99\u3002"}}},"sea-dragon-gate":{name:{en:"Dragon-Mouth Gate",zh:"\u9F99\u53E3\u95E8"},desc:{en:"A gate whose arch is a dragon's open jaws, above a stair down to the water. It adapts the Great Hall's entrance, which the books describe as a dragon's mouth.",zh:"\u95E8\u62F1\u5851\u6210\u5DE8\u9F99\u5F20\u5F00\u7684\u5927\u53E3\uFF0C\u5176\u4E0B\u77F3\u9636\u901A\u5411\u6C34\u8FB9\u3002\u5B83\u6539\u7F16\u81EA\u4E66\u4E2D\u5927\u5385\u7684\u5165\u53E3\u2014\u2014\u90A3\u5165\u53E3\u6B63\u662F\u4E00\u5F20\u9F99\u53E3\u3002"},tour:{en:"In the books, men enter the Great Hall through a stone dragon's jaws; here the jaws become a gate.",zh:"\u4E66\u4E2D\uFF0C\u4EBA\u4EEC\u987B\u7A7F\u8FC7\u77F3\u9F99\u7684\u5927\u53E3\u624D\u80FD\u8FDB\u5165\u5927\u5385\uFF1B\u672C\u573A\u666F\u628A\u8FD9\u5F20\u9F99\u53E3\u505A\u6210\u4E86\u57CE\u95E8\u3002"},source:{confidence:"low",refs:["acok","awoiaf"],book:{en:`The Great Hall is shaped like a dragon lying on its belly, entered through its open mouth. A separate Sea Dragon Tower holds the maester's rooms and rookery. No "Sea Dragon Gate" is attested.`,zh:"\u5927\u5385\u5F62\u5982\u4E00\u6761\u4F0F\u5730\u7684\u5DE8\u9F99\uFF0C\u987B\u4ECE\u5176\u5F20\u5F00\u7684\u53E3\u4E2D\u8FDB\u5165\u3002\u53E6\u6709\u6D77\u9F99\u5854\uFF0C\u5B66\u58EB\u5C45\u6240\u4E0E\u9E26\u5DE2\u90FD\u5728\u5176\u4E2D\u3002\u4E66\u4E2D\u6CA1\u6709\u201C\u6D77\u9F99\u95E8\u201D\u3002"},unknown:{en:"The form and position of the castle's real gates.",zh:"\u57CE\u5821\u771F\u6B63\u7684\u57CE\u95E8\u5F62\u5236\u4E0E\u4F4D\u7F6E\u3002"},interpretation:{en:"A pylon gate with an open-mouthed head, glowing eyes and fangs on the south-east, above a stair to a dock.",zh:"\u4E1C\u5357\u4FA7\u7684\u5854\u95E8\u5F0F\u57CE\u95E8\uFF0C\u9F99\u9996\u5F20\u53E3\uFF0C\u53CC\u76EE\u53D1\u5149\u3001\u7360\u7259\u6BD5\u9732\uFF0C\u4E0B\u6709\u77F3\u9636\u901A\u5F80\u7801\u5934\u3002"}}},"painted-table-chamber":{name:{en:"Painted Table Chamber",zh:"\u5F69\u7ED8\u684C\u5385"},desc:{en:"A round chamber atop the Stone Drum around a huge table carved and painted as a map of Westeros, made for Aegon the Conqueror. A cutaway shows the room.",zh:"\u77F3\u9F13\u697C\u9876\u5C42\u7684\u5706\u5385\uFF0C\u4E2D\u592E\u662F\u4E00\u5F20\u4E3A\u5F81\u670D\u8005\u4F0A\u803F\u6253\u9020\u7684\u5DE8\u684C\uFF0C\u96D5\u7ED8\u6210\u7EF4\u65AF\u7279\u6D1B\u5730\u56FE\u3002\u53EF\u8FDB\u5165\u5256\u9762\u67E5\u770B\u5385\u5185\u3002"},tour:{en:"A table carved as Westeros: Aegon planned his conquest here, and Stannis his war.",zh:"\u96D5\u6210\u7EF4\u65AF\u7279\u6D1B\u5F62\u72B6\u7684\u5DE8\u684C\uFF1A\u4F0A\u803F\u5728\u6B64\u8C0B\u5212\u5F81\u670D\uFF0C\u53F2\u5766\u5C3C\u65AF\u5728\u6B64\u7B79\u5212\u6218\u4E8B\u3002"},source:{confidence:"high",refs:["acok","twoiaf"],book:{en:"At the top of the Stone Drum, a great table shaped and painted as Westeros, made for Aegon I; Stannis holds council around it.",zh:"\u77F3\u9F13\u697C\u9876\u5C42\u6709\u4E00\u5F20\u96D5\u7ED8\u6210\u7EF4\u65AF\u7279\u6D1B\u5F62\u72B6\u7684\u5DE8\u684C\uFF0C\u4E3A\u4F0A\u803F\u4E00\u4E16\u6240\u9020\uFF1B\u53F2\u5766\u5C3C\u65AF\u5728\u684C\u65C1\u53EC\u96C6\u8BAE\u4E8B\u3002"},unknown:{en:"The room's size and the table's exact dimensions.",zh:"\u5385\u5BA4\u5927\u5C0F\u4E0E\u684C\u5B50\u7684\u786E\u5207\u5C3A\u5BF8\u3002"},interpretation:{en:"A roughly round room with sea windows and a lacquered map table; the coastline is only a rough sketch.",zh:"\u8FD1\u5706\u5F62\u5385\u5BA4\uFF0C\u4E34\u6D77\u5F00\u7A97\uFF0C\u4E2D\u592E\u662F\u6F06\u7ED8\u5730\u56FE\u684C\uFF1B\u6D77\u5CB8\u7EBF\u53EA\u662F\u7C97\u7565\u793A\u610F\u3002"}}},"dragon-gargoyles":{name:{en:"Dragon Gargoyles",zh:"\u9F99\u5F62\u6EF4\u6C34\u517D"},desc:{en:"Stone dragons and other monsters crouch along walls and towers; the castle looks shaped rather than built.",zh:"\u77F3\u9F99\u4E0E\u79CD\u79CD\u602A\u517D\u8E72\u8E1E\u5728\u5899\u5934\u5854\u9876\uFF0C\u6574\u5EA7\u57CE\u5821\u4EFF\u4F5B\u662F\u5851\u51FA\u6765\u7684\uFF0C\u800C\u975E\u780C\u51FA\u6765\u7684\u3002"},tour:{en:"Thousands of stone dragons, wyverns and hellhounds keep watch from the walls.",zh:"\u6210\u5343\u4E0A\u4E07\u7684\u77F3\u9F99\u3001\u98DE\u9F99\u4E0E\u5730\u72F1\u72AC\u4ECE\u5899\u5934\u4FEF\u89C6\u3002"},source:{confidence:"high",refs:["acok","twoiaf"],book:{en:"The Valyrians shaped the castle's stone into dragons, gargoyles and other beasts, reportedly by sorcery.",zh:"\u74E6\u96F7\u5229\u4E9A\u4EBA\u628A\u57CE\u5821\u7684\u77F3\u5934\u5851\u6210\u5DE8\u9F99\u3001\u6EF4\u6C34\u517D\u4E0E\u5176\u4ED6\u602A\u517D\uFF0C\u636E\u8BF4\u7528\u7684\u662F\u5DEB\u672F\u3002"},unknown:{en:"Their number, size and exact placement.",zh:"\u6570\u91CF\u3001\u5927\u5C0F\u4E0E\u5177\u4F53\u4F4D\u7F6E\u3002"},interpretation:{en:"Small drakes sit at intervals along the wall-top, with a larger one on each tower; only dragons are shown.",zh:"\u5899\u9876\u6BCF\u9694\u4E00\u6BB5\u8E72\u4E00\u5934\u5C0F\u9F99\uFF0C\u6BCF\u5EA7\u5854\u4E0A\u5404\u6709\u4E00\u5934\u5927\u9F99\uFF1B\u53EA\u8868\u73B0\u4E86\u9F99\u5F62\u3002"}}},"castle-walls":{name:{en:"Walls and Towers",zh:"\u57CE\u5899\u4E0E\u5854\u697C"},desc:{en:"A black curtain wall hugging the headland, slender spired towers alternating with square bastions.",zh:"\u7D27\u8D34\u6D77\u5CAC\u7684\u9ED1\u8272\u5E55\u5899\uFF0C\u7EC6\u9AD8\u5C16\u5854\u4E0E\u65B9\u5F62\u68F1\u5821\u4EA4\u66FF\u800C\u7ACB\u3002"},tour:{en:"Black walls follow the headland, towers rising like fangs.",zh:"\u9ED1\u5899\u6CBF\u6D77\u5CAC\u873F\u8712\uFF0C\u5854\u697C\u5982\u7360\u7259\u822C\u8038\u8D77\u3002"},source:{confidence:"medium",refs:["acok"],book:{en:"The castle has high walls and towers of black stone.",zh:"\u57CE\u5821\u6709\u9ED1\u77F3\u780C\u6210\u7684\u9AD8\u5899\u4E0E\u5854\u697C\u3002"},unknown:{en:"Number of towers, wall height and layout.",zh:"\u5854\u697C\u6570\u91CF\u3001\u5899\u9AD8\u4E0E\u5E03\u5C40\u3002"},interpretation:{en:"An oval ring of eighteen towers; the plan is invented.",zh:"\u5341\u516B\u5EA7\u5854\u697C\u7EC4\u6210\u7684\u692D\u5706\u73AF\uFF1B\u5E73\u9762\u4E3A\u81EA\u62DF\u3002"}}},"harbor-village":{name:{en:"Harbour and Village",zh:"\u6E2F\u53E3\u4E0E\u6751\u9547"},desc:{en:"A fishing village and small harbour on a sheltered cove below the castle, linked to it by a climbing road.",zh:"\u57CE\u5821\u4E0B\u65B9\u907F\u98CE\u5C0F\u6E7E\u91CC\u7684\u6E14\u6751\u4E0E\u5C0F\u6E2F\uFF0C\u4E00\u6761\u76D8\u5C71\u8DEF\u901A\u5F80\u57CE\u5821\u3002"},tour:{en:"Below the black castle lies the harbour where Stannis's fleet gathers.",zh:"\u9ED1\u8272\u57CE\u5821\u4E4B\u4E0B\u662F\u6E2F\u53E3\uFF0C\u53F2\u5766\u5C3C\u65AF\u7684\u8230\u961F\u5728\u6B64\u96C6\u7ED3\u3002"},source:{confidence:"medium",refs:["acok"],book:{en:"A harbour and a small town lie below the castle; Stannis gathers ships there.",zh:"\u57CE\u5821\u4E0B\u65B9\u6709\u6E2F\u53E3\u4E0E\u5C0F\u9547\uFF1B\u53F2\u5766\u5C3C\u65AF\u5728\u6B64\u96C6\u7ED3\u8239\u53EA\u3002"},unknown:{en:"The town's name, size and layout.",zh:"\u5C0F\u9547\u7684\u540D\u79F0\u3001\u89C4\u6A21\u4E0E\u5E03\u5C40\u3002"},interpretation:{en:"About seventy cottages around a cove with two piers; location invented.",zh:"\u6D77\u6E7E\u8FB9\u7EA6\u4E03\u5341\u95F4\u5C0F\u5C4B\u4E0E\u4E24\u5EA7\u6808\u6865\uFF1B\u4F4D\u7F6E\u4E3A\u81EA\u62DF\u3002"}}},"dragonglass-slopes":{name:{en:"Dragonglass Slopes",zh:"\u9F99\u6676\u5C71\u5761"},desc:{en:"Black volcanic slopes where dragonglass might lie, with steam vents and glowing ground near the crater.",zh:"\u6216\u8BB8\u57CB\u6709\u9F99\u6676\u7684\u9ED1\u8272\u706B\u5C71\u5761\uFF0C\u9760\u8FD1\u706B\u5C71\u53E3\u5904\u6709\u55B7\u6C14\u5B54\u4E0E\u6CDB\u7EA2\u7684\u5730\u9762\u3002"},tour:{en:"Dragonglass is volcanic glass; an island of fire is a natural place to look for it.",zh:"\u9F99\u6676\u662F\u706B\u5C71\u73BB\u7483\uFF1B\u8FD9\u5EA7\u706B\u4E4B\u5C9B\u81EA\u7136\u662F\u5BFB\u627E\u5B83\u7684\u597D\u53BB\u5904\u3002"},spoiler:{en:"Later books mention dragonglass in the old tunnels under Dragonstone and plans to mine it for the war in the north.",zh:"\u540E\u7EED\u5404\u5377\u63D0\u5230\u9F99\u77F3\u5C9B\u5730\u4E0B\u7684\u65E7\u96A7\u9053\u4E2D\u6709\u9F99\u6676\uFF0C\u5E76\u8BA1\u5212\u5F00\u91C7\u4EE5\u4F9B\u5317\u65B9\u4E4B\u6218\u3002"},source:{confidence:"low",refs:["asos","adwd"],book:{en:"Dragonglass (obsidian) is linked to Dragonstone in later books; no slopes or mines are described.",zh:"\u540E\u7EED\u5404\u5377\u5C06\u9F99\u6676\uFF08\u5373\u9ED1\u66DC\u77F3\uFF09\u4E0E\u9F99\u77F3\u5C9B\u8054\u7CFB\u5728\u4E00\u8D77\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u5C71\u5761\u6216\u77FF\u5751\u3002"},unknown:{en:"Where it lies and how much there is.",zh:"\u57CB\u85CF\u4F4D\u7F6E\u4E0E\u50A8\u91CF\u3002"},interpretation:{en:"Only dark, glassy slopes with vents; no mine is drawn.",zh:"\u4EC5\u4EE5\u6697\u8272\u73BB\u7483\u8D28\u5C71\u5761\u4E0E\u55B7\u6C14\u5B54\u793A\u610F\uFF1B\u672A\u7ED8\u77FF\u5751\u3002"}}},"shingle-shore":{name:{en:"Black Shore",zh:"\u9ED1\u8272\u6D77\u5CB8"},desc:{en:"A black coast of cliffs and shingle on the open-sea side, battered by wind and surf.",zh:"\u671D\u5411\u5916\u6D77\u4E00\u4FA7\u7684\u9ED1\u8272\u60AC\u5D16\u4E0E\u783E\u6EE9\uFF0C\u7EC8\u5E74\u53D7\u98CE\u6D6A\u62CD\u6253\u3002"},tour:{en:"Open sea and black cliffs: Dragonstone looks out over the Narrow Sea.",zh:"\u5F00\u9614\u6D77\u9762\u4E0E\u9ED1\u8272\u60AC\u5D16\uFF1A\u9F99\u77F3\u5C9B\u9762\u671D\u72ED\u6D77\u3002"},source:{confidence:"low",refs:["acok","maps"],book:{en:"The island lies where Blackwater Bay opens into the Narrow Sea.",zh:"\u8BE5\u5C9B\u4F4D\u4E8E\u9ED1\u6C34\u6E7E\u901A\u5F80\u72ED\u6D77\u4E4B\u5904\u3002"},unknown:{en:"The coastline and cliff heights.",zh:"\u6D77\u5CB8\u7EBF\u5F62\u72B6\u4E0E\u5D16\u9AD8\u3002"},interpretation:{en:"A scenic coast only; nothing here is described in the books.",zh:"\u4EC5\u4E3A\u6D77\u5CB8\u666F\u89C2\uFF1B\u4E66\u4E2D\u5E76\u65E0\u6B64\u5904\u63CF\u5199\u3002"}}}}};export{e as default};
